use anyhow :: { Context , Result } ; use serde :: { Deserialize , Serialize } ; use std :: fs ; use std :: path :: Path ; use super :: * ; use serde_json :: json ; use tempfile :: NamedTempFile ; # [doc = " Create a matrix row for trace encoding"] fn matrix_row (step : i64 , period : i64 , ts_gap : i64 , pid : i64 , tid : i64 , cpu_mode : & str) -> Vec < f64 > { let period_val = if period > 0 { (period as f64 + 1.0) . log10 () } else { 0.0 } ; let ts_gap_val = if ts_gap != 0 { (ts_gap . abs () as f64 + 1.0) . log10 () } else { 0.0 } ; let cpu_signal = CPU_MODE_SIGNAL . iter () . find (| (mode , _) | * mode == cpu_mode) . map (| (_ , sig) | * sig) . unwrap_or (0.0) ; vec ! [step as f64 , period_val , ts_gap_val , pid as f64 , tid as f64 , cpu_signal ,] }